-- Paramètres fiscaux et sociaux des 10 marchés de la zone franc (23/11/2026).
-- Toutes les valeurs sont des estimations sourcées (PwC, Cleiss, presse) ; les valeurs prudentes le disent dans leur note.
-- Le Tchad, la Centrafrique, la Guinée équatoriale et la Guinée-Bissau restent inactifs faute de sources suffisantes.

update public.countries set is_active = false where code in ('TD', 'CF', 'GQ', 'GW');
update public.countries set data_level = 'sourcee' where code in ('BJ', 'BF', 'ML', 'NE');
update public.countries set priority = 10 where code = 'NE';
update public.countries set priority = 30 where code = 'TD';

