insert into public.tax_parameters (country_code, code, label, value, unit, valid_from, source_id, verified_at, status, note, monthly_ceiling)
select v.cc, v.code, coalesce(v.label, case v.code when 'is_taux' then 'Impôt sur les sociétés (taux de droit commun)' when 'imf_taux' then 'Impôt minimum (en % du chiffre d''affaires)' when 'minimum_perception' then 'Minimum de perception' when 'minimum_dispense_annees' then 'Exercices dispensés du minimum d''impôt (entreprise nouvelle)' when 'deficit_report_annees' then 'Report des déficits' when 'revenu_minimum_mensuel' then 'Salaire minimum mensuel (SMIG)' when 'tva_taux' then 'TVA, taux normal' when 'isl_seuil_ca' then 'Régime des petites entreprises : chiffre d''affaires annuel inférieur à' end), v.value,
