join public.sources s on s.title = case v.s when 'ci' then 'PwC Worldwide Tax Summaries — Côte d''Ivoire' when 'cm' then 'PwC Worldwide Tax Summaries — Cameroun' when 'sn' then 'PwC Worldwide Tax Summaries — Sénégal' when 'cg' then 'PwC Worldwide Tax Summaries — Congo' when 'tg' then 'PwC Ghana — Togo Tax Facts and Figures 2026' when 'qc' then 'PwC Worldwide Tax Summaries — taux d''IS et de TVA (Quick Charts)' when 'smig' then 'Salaires minimums en Afrique de l''Ouest et du Centre (presse, 2026)' when 'smig2' then 'SMIG dans l''UEMOA en 2026 (presse)' when 'pru' then 'Valeur prudente AfriBiz, à vérifier' when 'cl_cg' then 'Cleiss — cotisations au Congo (2023)' when 'cl_bj' then 'Cleiss — cotisations au Bénin (2024)' when 'cl_ne' then 'Cleiss — cotisations au Niger (2024)' when 'cl_ml' then 'Cleiss — régime malien de sécurité sociale' when 'ad_bj' then 'Agence ADOCC — Bénin, taux d''imposition' when 'ad_ne' then 'Agence ADOCC — Niger, taux d''imposition' when 'tr_bj' then 'TaxRatesByCountry — Bénin 2026' when 'tr_bf' then 'TaxRatesByCountry — Burkina Faso 2026' when 'tr_ml' then 'TaxRatesByCountry — Mali 2026' when 'ac_bf' then 'AfriCarrières — charges employeur au Burkina Faso' when 'ac_ml' then 'AfriCarrières — charges employeur au Mali' end
where not exists (select 1 from public.tax_parameters t where t.country_code = v.cc and t.code = v.code);
